/**
 * /sitemap/ —— HTML 站点地图
 *
 * 🔴 **为什么在已经有 `sitemap.xml` 的情况下还要一个 HTML 版**：
 *    XML 版是给爬虫的，但一个 100+ 页的站点需要一个**人能看懂的全站入口** ——
 *    它同时解决两件事：① 让人不用猜 URL 结构；② 给爬虫一张全站内链图
 *    （XML 只声明「这些地址存在」，HTML 版本额外产出一条真实内链）。
 *    两者不冲突：XML 在 `/sitemap-index.xml`，本页在 `/sitemap/`。
 *
 * 🔴 **清单来源就是各数据文件本身**，不手写第二份 —— 手写一份必然与真实路由漂移，
 *    而漂移的站点地图比没有更糟（它会把不存在的页也指出来）。
 *    页面清单里**不含**重定向桩（`/cart-rescue/*`，它们只是跳转，不是内容）。
 *
 * @author 恒哥
 * @since 2026-10-13
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { FAMILIES } from '../data/families';
import { INDUSTRIES } from '../data/industries';
import { FEATURES } from '../data/features';
import { USE_CASES } from '../data/useCases';
import { COMPARISONS } from '../data/compare';
import { CHANNELS, INTEGRATIONS, channelMeta, integrationsInChannel } from '../data/integrations';
import { GUIDES } from '../data/guides';
import { SOLUTIONS } from '../data/solutions';
import { HELP_ARTICLES } from '../data/help';
import { MESSAGING_PRODUCT_NAME, PRODUCT_NAME } from '../constants/brand';
import '../styles/marketing.css';
import T from '../i18n/LocalizedText';
import { usePageI18n } from '../i18n';

/** 手写页清单（唯一一处需要人工维护的列表；改了页面就改这里） */
const STATIC_SECTIONS = [
  {
    title: 'Whaleal Platform',
    links: [
      { to: '/platform/', label: 'Overview' },
      { to: '/platform/sms/', label: 'SMS channel' },
      { to: '/platform/pricing/', label: 'Pricing' },
      { to: '/platform/roadmap/', label: 'Channels and status' },
      { to: '/integrations/', label: 'Provider integrations' },
      { to: '/guides/', label: 'Guides' },
      { to: '/help/', label: 'Help center' },
    ],
  },
  {
    title: PRODUCT_NAME,
    links: [
      { to: '/pricing/', label: 'Pricing' },
      { to: '/products/', label: 'Products' },
      { to: '/install/', label: 'Install' },
      { to: '/solutions/', label: 'Solutions' },
      { to: '/features/ai-email-engine/', label: 'Recovery emails' },
    ],
  },
  {
    title: 'Company',
    links: [
      { to: '/about/', label: 'About' },
      { to: '/customers/', label: 'Customers' },
      { to: '/contact/', label: 'Contact' },
      { to: '/security/', label: 'Security' },
      { to: '/status/', label: 'Service status' },
      { to: '/changelog/', label: 'Changelog' },
      { to: '/faq/', label: 'FAQ' },
      { to: '/sitemap/', label: 'Site map (this page)' },
    ],
  },
  {
    title: 'Legal',
    links: [
      { to: '/privacy/', label: 'Privacy policy' },
      { to: '/terms/', label: 'Terms of service' },
      { to: '/gdpr/', label: 'GDPR' },
    ],
  },
];

const FAMILY_DATA = {
  industries: INDUSTRIES,
  features: FEATURES,
  'use-cases': USE_CASES,
  compare: COMPARISONS,
};

/** 各族标题字段不统一（guides/help 是 title，其余是 name）—— 在本处统一，别去改数据 */
const label = (p) => p.title || p.name;

export default function SitemapPage(pageContext) {
  const { locale, localePath } = usePageI18n(pageContext);

  const familyCount = Object.keys(FAMILY_DATA).reduce((n, k) => n + FAMILY_DATA[k].length, 0);
  const detailCount = familyCount + INTEGRATIONS.length + GUIDES.length + SOLUTIONS.length + HELP_ARTICLES.length;

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title="Site map — every page on whaleal.com"
        description="A single index of every page on this site: platform sections, integrations, guides, help articles, solutions and legal pages."
        pathname="/sitemap/"
        softwareApp={false} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="sitemap.001">Site map</T></span>
          <h1><T id="sitemap.002">Every page on this site</T></h1>
          <p className="mk-lead"><T id="sitemap.003">
            One index for the whole site — useful if you would rather scan a list than guess at URL
            structure. It covers the platform sections, every integration, guide, help article and
            solution page, plus company and legal pages.
          </T></p>
        </header>

        <section className="mk-section">
          <h2><T id="sitemap.004">Platform sections</T></h2>
          <div className="mk-grid">
            {Object.keys(FAMILIES).map((k) => {
              const f = FAMILIES[k];
              return (
                <article className="mk-card" key={k}>
                  <span className="mk-card-tag">{f.eyebrow}</span>
                  <h3>
                    <Link to={f.indexPath}>{f.label}</Link>
                  </h3>
                  <p>{f.lede}</p>
                  <ul className="mk-list">
                    {FAMILY_DATA[k].map((p) => (
                      <li key={p.slug}>
                        <Link to={`${f.indexPath}${p.slug}/`}>{label(p)}</Link>
                      </li>
                    ))}
                  </ul>
                </article>
              );
            })}
          </div>
        </section>

        <section className="mk-section">
          <h2><T id="sitemap.005">{MESSAGING_PRODUCT_NAME} — integrations and content</T></h2>
          <div className="mk-grid">
            <article className="mk-card">
              <h3>
                <Link to={localePath("/integrations/")}><T id="sitemap.006">Integrations</T></Link>
              </h3>
              {CHANNELS.map((c) => {
                const rows = integrationsInChannel(c.id);
                return (
                  <div className="mk-sitemap-group" key={c.id}>
                    <p className="mk-sitemap-group-label">
                      {channelMeta(c.id).label} — {rows.length}
                    </p>
                    <ul className="mk-list">
                      {rows.map((i) => (
                        <li key={i.slug}>
                          <Link to={`/integrations/${i.slug}/`}>{i.name}</Link>
                        </li>
                      ))}
                    </ul>
                  </div>
                );
              })}
            </article>
            <article className="mk-card">
              <h3>
                <Link to={localePath("/guides/")}><T id="sitemap.007">Guides</T></Link>
              </h3>
              <ul className="mk-list">
                {GUIDES.map((g) => (
                  <li key={g.slug}>
                    <Link to={`/guides/${g.slug}/`}>{label(g)}</Link>
                  </li>
                ))}
              </ul>
            </article>
            <article className="mk-card">
              <h3>
                <Link to={localePath("/help/")}><T id="sitemap.008">Help center</T></Link>
              </h3>
              <ul className="mk-list">
                <li>
                  <Link to={localePath("/help/cart/")}><T id="sitemap.009">Whaleal Cart help</T></Link>
                </li>
                {HELP_ARTICLES.map((h) => (
                  <li key={h.slug}>
                    <Link to={`/help/${h.slug}/`}>{label(h)}</Link>
                  </li>
                ))}
              </ul>
            </article>
            <article className="mk-card">
              <h3>
                <Link to={localePath("/solutions/")}><T id="sitemap.010">Solutions</T></Link>
              </h3>
              <ul className="mk-list">
                {SOLUTIONS.map((s) => (
                  <li key={s.slug}>
                    <Link to={`/solutions/${s.slug}/`}>{label(s)}</Link>
                  </li>
                ))}
              </ul>
            </article>
          </div>
        </section>

        <section className="mk-section">
          <h2><T id="sitemap.011">Company and product pages</T></h2>
          <div className="mk-grid">
            {STATIC_SECTIONS.map((sec) => (
              <article className="mk-card" key={sec.title}>
                <h3>{sec.title}</h3>
                <ul className="mk-list">
                  {sec.links.map((l) => (
                    <li key={l.to}>
                      <Link to={l.to}>{l.label}</Link>
                    </li>
                  ))}
                </ul>
              </article>
            ))}
          </div>
        </section>

        <div className="mk-scope">
          <T id="sitemap.012"><strong>Scope.</strong> This page indexes {detailCount} content pages plus the platform
          index pages. Legacy redirect addresses are intentionally not listed, because a redirect is
          not a page. The machine-readable version is published separately for search engines.
        </T></div>
      </div>
    </Layout>
  );
}
